INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Minimierung von Soll-Ist-Abweichungen Teil des Controllings?', 2, '[{"text": "Ja", "correct": true, "because": "Korrigiert Abweichungen"}, {"text": "Nein", "correct": false, "because": "Es gehört zum Controlling"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel hat die Minimierung von Soll-Ist-Abweichungen?', 3, '[{"text": "Projektziele sichern", "correct": true, "because": "Hält Plan ein"}, {"text": "Teamgröße festlegen", "correct": false, "because": "Planungsaspekt"}, {"text": "Neue Ziele definieren", "correct": false, "because": "Initiierungsschritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Minimierung korrigiert Abweichungen. b) Sie erfolgt nur am Projektende.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, fortlaufend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren führen zu Soll-Ist-Abweichungen?', 4, '[{"text": "Zeitverzögerungen", "correct": true, "because": "Verschieben Termine"}, {"text": "Unklare Ziele", "correct": false, "because": "Planungsproblem"}, {"text": "Kostenüberschreitungen", "correct": true, "because": "Überschreiten Budget"}, {"text": "Qualitätsmängel", "correct": true, "because": "Abweichung von Standards"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Controlling ohne Minimierung von Abweichungen effektiv sein?', 2, '[{"text": "Nein", "correct": true, "because": "Korrektur essenziell"}, {"text": "Ja", "correct": false, "because": "Abweichungen bleiben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft bei der Minimierung von Abweichungen?', 3, '[{"text": "Earned Value Management", "correct": true, "because": "Misst Fortschritt"}, {"text": "Keine Überwachung", "correct": false, "because": "Fehlt Kontrolle"}, {"text": "Zufällige Checks", "correct": false, "because": "Unsystematisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Minimierung von Abweichungen nur für große Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen sie"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Minimierung von Soll-Ist-Abweichungen?', 3, '[{"text": "Projekt auf Plan halten", "correct": true, "because": "Passt Kurs an"}, {"text": "Technische Lösung finden", "correct": false, "because": "Durchführungsaspekt"}, {"text": "Planung neu starten", "correct": false, "because": "Planungsaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Minimierung erfordert Ist-Daten. b) Sie ist immer vermeidbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Abweichungen üblich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Minimierung von Abweichungen?', 3, '[{"text": "Projektziele gefährdet", "correct": true, "because": "Abweichungen wachsen"}, {"text": "Projekt wird effizienter", "correct": false, "because": "Eher Chaos"}, {"text": "Kosten sinken", "correct": false, "because": "Können steigen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Minimierung ohne Zeitplan erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Zeitbasis fehlt"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt Minimierung von Abweichungen?', 3, '[{"text": "Meilenstein um 1 Woche verschieben", "correct": true, "because": "Konkret und real"}, {"text": "Irgendwas anpassen", "correct": false, "because": "Zu vage"}, {"text": "Team soll schneller sein", "correct": false, "because": "Keine Korrektur"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Minimierung nur für den Projektleiter relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Team muss mitwirken"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Minimierung von Abweichungen?', 4, '[{"text": "Abweichungen erkennen", "correct": true, "because": "Erster Schritt"}, {"text": "Unklare Maßnahmen", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Korrekturmaßnahmen planen", "correct": true, "because": "Passt Plan an"}, {"text": "Umsetzung überwachen", "correct": true, "because": "Sichert Erfolg"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Minimierung dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachvollziehbarkeit wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft bei der Minimierung?', 3, '[{"text": "Abweichungsanalyse", "correct": true, "because": "Identifiziert Probleme"}, {"text": "Keine Überprüfung", "correct": false, "because": "Fehlt Kontrolle"}, {"text": "Spontane Änderungen", "correct": false, "because": "Unsystematisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Minimierung ohne Controlling-Daten erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Datenbasis fehlt"}, {"text": "Ja", "correct": false, "because": "Uninformiert unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Minimierung?', 3, '[{"text": "Fehlende Fortschrittsdaten", "correct": true, "because": "Verhindern Analyse"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Korrektur"}, {"text": "Gute Kommunikation", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Minimierung passt die Planung an. b) Sie ist nur für Kosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, umfassender"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Minimierung?', 3, '[{"text": "Projekt auf Kurs halten", "correct": true, "because": "Verhindert Versagen"}, {"text": "Maximale Abweichungen", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Anpassung", "correct": false, "because": "Fördert Flexibilität"}]');
